program:
procedure WatchesCollectedFollowUp {
  about "Follow up with owners marked collected"
  policy WatchesPolicy
  sheet Watches "Watches" { owner: Text, email: Email, ready_on: Date, status: Text, quote: Money, serial_number: Text private }
  trigger every day at 10:00

  let all = fetch Watches
  let recent = filter all where status == "collected" and days_between(ready_on, today()) <= 7 and days_between(ready_on, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no collected owners"
  }
  notify owner "Collected owners to follow up: {n}"
  let msgs = draft each r in recent up to 40 email to r.email subject "Let's find a new time": "Hi {r.owner}, we're sorry we missed you. Reply to set up a new time."
  let ok = request batch approval of msgs from owner timeout 1 day else stop "batch not approved"
  send ok
  for each r in recent up to 40 {
    update r set status = "followed-up"
  }
}

procedure FencingRefunds {
  about "Handle refund requests within limits"
  policy FencingRefundPolicy
  sheet RefundRequests "RefundRequests" { request_id: Text, fencer: Text, email: Email, amount: Money, purchased: Date, status: Text }
  trigger when new row r in RefundRequests

  if days_between(r.purchased, today()) > 30 {
    notify owner "Refund request {r.request_id} is older than 30 days."
    stop "outside refund window"
  }
  if r.amount > $100.00 {
    notify owner "Refund request {r.request_id} is {r.amount}, over $100. Please review."
    stop "over refund limit"
  }
  if r.amount <= $15.00 {
    refund r.amount for r.request_id reason "refund request"
  } else {
    refund r.amount for r.request_id reason "refund request", ask owner first timeout 2 hours else stop "refund not approved"
  }
  update r set status = "refunded"
  let m = draft email to r.email subject "Your refund": "Hi {r.fencer}, your refund of {r.amount} has been issued."
  let ok = request approval of m from owner timeout 2 hours else stop "message not approved"
  send ok
}

procedure PoolcleanLateBalance {
  about "Remind late owners; escalate very late ones"
  policy PoolcleanPolicy
  sheet Cleanings "Cleanings" { owner: Text, phone: Phone, clean_on: Date, status: Text, fee: Money, gate_code: Text private }
  trigger every day at 09:00

  let all = fetch Cleanings
  let late = filter all where fee > $0.00 and days_between(clean_on, today()) > 5
  for each r in late up to 40 {
    if days_between(r.clean_on, today()) > 30 {
      notify owner "{r.owner} is very late ({r.fee}). Please call."
    } else {
      let m = draft sms to r.phone: "Hello {r.owner default 'there'}, our records show a fee of {r.fee}. Questions? Just reply."
      let ok = request approval of m from owner timeout 2 hours else skip
      send ok
    }
  }
}

