procedure GamestoreConfirmNewGameNight {
  about "Confirm a new game night and add it to the calendar"
  policy GamestorePolicy
  sheet Tournaments "Tournaments" { player: Text, email: Email, event_at: DateTime, status: Text, entry: Money, birthdate: Text private }
  calendar Tables "Tables"
  trigger when new row r in Tournaments

  if r.event_at < now() + 2 hours {
    notify owner "Short-notice game night for {r.player} at {r.event_at}. Please handle it."
    stop "short notice goes to owner"
  }
  let m = draft email to r.email subject "Confirmed": "Hi {r.player default 'there'}, your game night with the store is confirmed for {r.event_at}."
  let ok = request approval of m from owner timeout 1 day else stop "confirmation not approved"
  send ok
  let ev = book Tables { title: "{r.player}", at: r.event_at, length: 45 minutes }
  update r set status = "confirmed"
}

