procedure BowlingRefunds {
  about "Handle refund requests within limits"
  policy BowlingRefundPolicy
  sheet RefundRequests "RefundRequests" { request_id: Text, bowler: Text, phone: Phone, amount: Money, purchased: Date, status: Text }
  trigger when new row r in RefundRequests

  if days_between(r.purchased, today()) > 30 {
    notify owner "Refund request {r.request_id} is older than 30 days."
    stop "outside refund window"
  }
  if r.amount > $50.00 {
    notify owner "Refund request {r.request_id} is {r.amount}, over $50. Please review."
    stop "over refund limit"
  }
  if r.amount <= $15.00 {
    refund r.amount for r.request_id reason "refund request"
  } else {
    refund r.amount for r.request_id reason "refund request", ask owner first timeout 2 hours else stop "refund not approved"
  }
  update r set status = "refunded"
  let m = draft sms to r.phone: "Hi {r.bowler default 'there'}, your refund of {r.amount} has been issued."
  let ok = request approval of m from owner timeout 2 hours else stop "message not approved"
  send ok
}

