  limit order $600 per day
}

program:
procedure CatcafeReorder {
  about "Reorder cat treats below their minimum"
  policy CatcafeStockPolicy
  sheet Treats "Treats" { treat: Text, bags: Number, minimum: Number, reorder_qty: Number, vendor: Text, unit_cost: Money }
  trigger every day at 17:30

  let all = fetch Treats
  let low = filter all where bags < minimum
  for each i in low up to 3 {
    let cost = i.reorder_qty * i.unit_cost
    if cost > $200.00 {
      notify owner "Reorder of {i.treat} would cost {cost}, over the $200 limit."
      skip
    }
    order "{i.reorder_qty} x {i.treat}" from i.vendor cost cost, ask owner first timeout 1 day else skip
    log "ordered {i.treat}"
  }
}

