  limit order $200 per action
  limit order $400 per day
}

program:
procedure AquariumReorder {
  about "Reorder fish food below their minimum"
  policy AquariumStockPolicy
  sheet FishFood "FishFood" { food: Text, tins: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every day at 17:30

  let all = fetch FishFood
  let low = filter all where tins < minimum
  for each i in low up to 2 {
    let cost = i.reorder_qty * i.unit_cost
    if cost > $200.00 {
      notify owner "Reorder of {i.food} would cost {cost}, over the $200 limit."
      skip
    }
    order "{i.reorder_qty} x {i.food}" from i.supplier cost cost, ask owner first timeout 12 hours else skip
    log "ordered {i.food}"
  }
}

