procedure FilmlabFilmDropOffReminders {
  about "Remind each photographer about their film drop-off"
  policy FilmlabPolicy
  sheet Rolls "Rolls" { photographer: Text, email: Email, dropped_on: Date, status: Text, cost: Money, card_hint: Text private }
  trigger every thursday at 09:00

  let all = fetch Rolls
  let due = filter all where dropped_on == today() + 7 days and status == "received"
  let msgs = draft each r in due up to 20 email to r.email subject "Your film drop-off in a week": "Hi {r.photographer default 'there'}, a reminder from the lab: your film drop-off is in a week."
