  }
}

procedure InteriorsLateBalance {
  about "Remind late clients; escalate very late ones"
  policy InteriorsPolicy
  sheet Projects "Projects" { client: Text, email: Email, review_on: Date, status: Text, retainer: Money, budget_notes: Text private }
  trigger every day at 08:00

  let all = fetch Projects
  let late = filter all where retainer > $0.00 and days_between(review_on, today()) > 3
  for each r in late up to 40 {
    if days_between(r.review_on, today()) > 14 {
      notify owner "{r.client} is very late ({r.retainer}). Please call."
    } else {
      let m = draft email to r.email subject "A friendly reminder": "Hello {r.client}, our records show a retainer of {r.retainer}. Questions? Just reply."
      let ok = request approval of m from owner timeout 12 hours else skip
      send ok
    }
  }
}

