      notify owner "Reorder of {i.color} would cost {cost}, over the $150 limit."
      skip
    }
    order "{i.reorder_qty} x {i.color}" from i.supplier cost cost, ask owner first timeout 6 hours else skip
    log "ordered {i.color}"
  }
}

