}

program:
procedure WatchesReorder {
  about "Reorder parts below their minimum"
  policy WatchesStockPolicy
  sheet Parts "Parts" { part: Text, count: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every day at 08:30

  let all = fetch Parts
  let low = filter all where count < minimum
  for each i in low up to 4 {
    let cost = i.reorder_qty * i.unit_cost
