  let old = filter all where days_between(dropped_on, today()) >= 60 and status != "lost"
  let oldest = sort old by dropped_on first 10
  for each r in oldest up to 10 {
    let m = draft email to r.email subject "We miss you": "Hi {r.photographer}, it's been a while! We'd love to see you again at the lab."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
  }
}

procedure ArcheryDailySummary {
  about "Tell the owner how many archers are booked"
  policy ArcheryPolicy
  sheet LaneBookings "LaneBookings" { archer: Text, email: Email, lane_at: DateTime, status: Text, fee: Money, medical_info: Text private }
  trigger every day at 17:30

  let all = fetch LaneBookings
  let these = filter all where status == "booked"
  let n = summarize count of these
  notify owner "Booked archers today: {n}"
}

procedure PoolDailySummary {
  about "Tell the owner how many swimmers are suspended"
  policy PoolPolicy
  sheet SwimPasses "SwimPasses" { swimmer: Text, email: Email, expires_on: Date, status: Text, fee: Money, health_flags: Text private }
  trigger every monday at 18:00

  let all = fetch SwimPasses
  let these = filter all where status == "suspended"
  let n = summarize count of these
  let total = summarize sum fee of these
  if n == 0 {
    stop "no suspended swimmers"
  }
  notify owner "Suspended swimmers: {n}, total fee: {total}"
}

procedure AquariumTankInstallReminders {
  about "Remind each customer about their tank install"
  policy AquariumPolicy
  sheet TankOrders "TankOrders" { customer: Text, phone: Phone, install_on: Date, status: Text, price: Money, home_access: Text private }
  trigger every day at 09:00

  let all = fetch TankOrders
  let due = filter all where install_on == today() + 7 days and status == "ordered"
  for each r in due up to 100 {
    let m = draft sms to r.phone: "Hi {r.customer default 'there'}, a reminder from the store: your tank install is in a week."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
  }
}

procedure PoolcleanPoolCleaningReminders {
  about "Remind each owner about their pool cleaning"
  policy PoolcleanPolicy
  sheet Cleanings "Cleanings" { owner: Text, phone: Phone, clean_on: Date, status: Text, fee: Money, gate_code: Text private }
  trigger every day at 10:00

  let all = fetch Cleanings
  let due = filter all where clean_on == today() + 3 days and status == "scheduled"
  let msgs = draft each r in due up to 100 sms to r.phone: "Hi {r.owner default 'there'}, a reminder from the service: your pool cleaning is in three days."
  let ok = request batch approval of msgs from owner timeout 6 hours else stop "batch not approved"
  send ok
  for each r in due up to 100 {
    update r set status = "reminded"
  }
}

procedure FilmlabCollectedFollowUp {
  about "Follow up with photographers marked collected"
  policy FilmlabPolicy
  sheet Rolls "Rolls" { photographer: Text, email: Email, dropped_on: Date, status: Text, cost: Money, card_hint: Text private }
  trigger every day at 17:30

  let all = fetch Rolls
  let recent = filter all where status == "collected" and days_between(dropped_on, today()) <= 1 and days_between(dropped_on, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no collected photographers"
  }
  notify owner "Collected photographers to follow up: {n}"
  let msgs = draft each r in recent up to 20 email to r.email subject "Let's find a new time": "Hi {r.photographer default 'there'}, we're sorry we missed you. Reply to set up a new time."
  let ok = request batch approval of msgs from owner timeout 1 day else stop "batch not approved"
  send ok
  for each r in recent up to 20 {
    update r set status = "followed-up"
  }
}
